# DISCLAMER: This file is generated by AI for testing purposes.
import tempfile
import unittest
from pathlib import Path

from iSpy.web.modules.logs import LogsModule


class LogTailTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)
        self.path = Path(self._tmp.name) / "log.txt"

    def test_legacy_locale_bytes_do_not_empty_the_view(self):
        # Regression: log handlers used the Windows locale encoding, so an em
        # dash was written as 0x97. Reading that as strict UTF-8 raised and the
        # API returned no lines at all.
        self.path.write_bytes(
            b"2026-01-01 INFO: camera ready\n"
            b"2026-01-01 ERROR: missing \x97 model file\n"
            b"2026-01-01 INFO: still running\n"
        )
        lines = LogsModule._efficient_tail(self.path, 3)
        self.assertEqual(len(lines), 3)
        self.assertIn("model file", lines[1])
        self.assertIn("still running", lines[2])

    def test_returns_only_the_requested_number_of_lines(self):
        self.path.write_text(
            "".join(f"line {i}\n" for i in range(10)), encoding="utf-8"
        )
        self.assertEqual(
            LogsModule._efficient_tail(self.path, 3),
            ["line 7", "line 8", "line 9"],
        )

    def test_last_line_without_a_trailing_newline_is_kept(self):
        self.path.write_text("first\nsecond\nthird", encoding="utf-8")
        self.assertEqual(
            LogsModule._efficient_tail(self.path, 2), ["second", "third"]
        )

    def test_tail_reads_across_multiple_chunks(self):
        # 200 KB forces the backwards reader through several 64 KB chunks.
        lines = [f"line {i:05d} " + ("x" * 80) for i in range(2000)]
        self.path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        tail = LogsModule._efficient_tail(self.path, 5)
        self.assertEqual(tail, lines[-5:])

    def test_missing_file_returns_no_lines(self):
        missing = Path(self._tmp.name) / "does-not-exist.txt"
        self.assertEqual(LogsModule._efficient_tail(missing, 10), [])


class LogsTemplateTests(unittest.TestCase):
    def test_entries_are_joined_with_newlines(self):
        template = (
            Path(__file__).resolve().parents[1]
            / "iSpy"
            / "web"
            / "templates"
            / "logs.html"
        ).read_text(encoding="utf-8")
        # .log-view uses white-space: pre-wrap; joining with an empty string
        # made every entry run together on one line.
        self.assertIn(".map(colorize).join('\\n')", template)


if __name__ == "__main__":
    unittest.main()
